const policies=[
{id:'tesu',school:'Thomas Edison State University',abbr:'TE',level:"Bachelor's",format:'Online',scope:'Undergraduate transfer policy',pct:95,note:'Four-year institutional credit may meet requirements except two TESU courses. Community-college credit is capped at 90. The 95% illustration assumes two 3-credit courses in a 120-credit degree; confirm residency fees and program rules.',url:'https://www.tesu.edu/student-resources/transfer-credits/index.php'},
{id:'cosc',school:'Charter Oak State College',abbr:'CO',level:"Bachelor's",format:'Online',scope:'Undergraduate transfer policy',pct:95,note:'Up to 114 credits from four-year institutions; up to 87 from two-year institutions. Cornerstone and capstone must be completed at Charter Oak. Major requirements still apply.',url:'https://www.charteroak.edu/prospective/admissions/transfer-students/'},
{id:'luonline',school:'Liberty University',abbr:'LU',level:"Bachelor's",format:'Online',scope:'Online undergraduate policy',pct:75,note:'Up to 75% of degree requirements. At least 25% of the major and degree must be completed through Liberty; program restrictions apply.',url:'https://catalog.liberty.edu/undergraduate/admission/admissions-online-program/'},
{id:'lucampus',school:'Liberty University',abbr:'LU',level:"Bachelor's",format:'Residential',scope:'Residential undergraduate policy',pct:75,note:'Residential admissions publishes a ceiling of 75%. This is not a promise of one-year completion: major residency, prerequisites, sequencing and course availability need review.',url:'https://www.liberty.edu/residential/undergraduate/transfer-students/policies-and-guidelines/'},
{id:'snhu',school:'Southern New Hampshire University',abbr:'SN',level:"Bachelor's",format:'Online',scope:'Online undergraduate transfer policy',pct:75,note:'Up to 90 credits toward a 120-credit bachelor’s degree. Your individual evaluation determines equivalencies and which credits satisfy the chosen program.',url:'https://www.snhu.edu/admission/transferring-credits'},
{id:'umgc',school:'University of Maryland Global Campus',abbr:'UM',level:"Bachelor's",format:'Online',scope:'Undergraduate transfer policy',pct:75,note:'Up to 90 credits from approved four-year institutions and other sources; two-year college credit has a 70-credit limit. Complete 30 credits at UMGC and confirm major rules.',url:'https://www.umgc.edu/help/article/transfer-undergraduate-credits-to-umgc'},
{id:'pg',school:'Purdue Global',abbr:'PG',level:"Bachelor's",format:'Online',scope:'Undergraduate prior-learning policy',pct:75,note:'External prior learning may cover up to 75% of an undergraduate credential. Quarter credits are used in many programs; 1 semester credit equals 1.5 quarter credits. Capstones are excluded.',url:'https://catalog.purdueglobal.edu/policy-information/prior-learning/'},
{id:'pgg',school:'Purdue Global',abbr:'PG',level:"Master's",format:'Online',scope:'Graduate prior-learning policy',pct:50,note:'Catalog ceiling for external prior learning is 50% of a graduate credential. Individual schools and programs may impose tighter limits. This is not a verified MBA equivalency map.',url:'https://catalog.purdueglobal.edu/policy-information/prior-learning/'},
{id:'snhua',school:'Southern New Hampshire University',abbr:'SN',level:'Associate',format:'Online',scope:'Associate transfer policy',pct:75,note:'Up to 45 of 60 credits toward an associate degree. Applicable degree requirements and the individual credit evaluation determine the actual award.',url:'https://www.snhu.edu/about-us/newsroom/education/what-are-transfer-credits'},
{id:'lumba',school:'Liberty University',abbr:'LU',level:"Master's",format:'Online',scope:'MBA · 36-hour program',pct:50,total:36,note:'The 2026–27 transfer matrix lists 18 of 36 hours as transferable for this MBA variant, with a 10-year credit-age limit. The 45-hour MBA has a different limit and is not represented here.',url:'https://catalog.liberty.edu/graduate/admission/graduate-admissions/transfer-credit-matrix/'},
{id:'ludba',school:'Liberty University',abbr:'LU',level:'Doctorate',format:'Online',scope:'Doctor of Business Administration',pct:50,total:60,note:'The 2026–27 matrix lists up to 30 of 60 hours and a 7-year credit-age limit with a footnote. Read the matrix and business-school restrictions; research requirements need separate confirmation.',url:'https://catalog.liberty.edu/graduate/admission/graduate-admissions/transfer-credit-matrix/'}
];
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let selected=new Set(),state={inventory:[],tasks:[],fields:{}};
try{const s=JSON.parse(localStorage.getItem('degreepath-v1'));if(s&&Array.isArray(s.inventory)&&s.fields)state=s}catch{}
const fields=['destination','goal','required','units','priority','rate','fees','pace','planned','notes'];
const tasks=['Read the current catalog and confirm this exact program’s transfer ceiling.','Request an official evaluation of all prior learning and transcripts.','Get written approval of each planned external course and its degree requirement.','Check major residency, upper-level credits, grades, credit age and prerequisites.','Confirm tuition, fees, aid, housing and course scheduling before enrolling.'];
$('destination').innerHTML=policies.map(p=>'<option value="'+p.id+'">'+esc(p.school+' — '+p.scope)+'</option>').join('');
fields.forEach(id=>{if(state.fields[id]!==undefined)$(id).value=state.fields[id];$(id).addEventListener('input',()=>{state.fields[id]=$(id).value;save();summary()})});
function save(){try{localStorage.setItem('degreepath-v1',JSON.stringify(state))}catch{$('message').textContent='Browser storage is unavailable. Download your plan to keep a copy.'}}
function render(){let list=policies.filter(p=>(!$('level').value||p.level===$('level').value)&&(!$('format').value||p.format===$('format').value)&&((p.school+' '+p.scope+' '+p.level).toLowerCase().includes($('search').value.toLowerCase())));list.sort($('sort').value==='transfer'?(a,b)=>b.pct-a.pct:(a,b)=>a.school.localeCompare(b.school));$('count').textContent=list.length+' policy scopes · '+new Set(list.map(p=>p.school)).size+' schools';$('cards').innerHTML=list.length?list.map(p=>'<article class="card"><div class="card-top"><span class="monogram">'+p.abbr+'</span><span class="pill">'+p.format+' · '+p.level+'</span></div><h3>'+p.school+'</h3><div class="scope">'+p.scope+'</div><div class="ceiling">'+p.pct+'% <small>maximum transfer potential*</small></div><div class="bar"><span style="width:'+p.pct+'%"></span></div><p>'+p.note+'</p><a class="source-link" href="'+p.url+'" target="_blank" rel="noopener">Read official policy ↗</a><div class="card-bottom"><button data-plan="'+p.id+'">Plan this route ↗</button><label><input type="checkbox" data-compare="'+p.id+'" '+(selected.has(p.id)?'checked':'')+'> Compare</label></div></article>').join(''):'<p>No researched policies match. Try a broader search. Coverage is expanding.</p>';document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{$('destination').value=b.dataset.plan;const p=policies.find(p=>p.id===b.dataset.plan);$('required').value=p.total||(p.level==='Associate'?60:120);$('units').value=p.id==='pg'?'Quarter':'Semester';state.inventory.forEach(c=>{c.status='pending'});state.tasks=[];fields.forEach(id=>state.fields[id]=$(id).value);save();inventory();summary();renderTasks();location.hash='workspace'});document.querySelectorAll('[data-compare]').forEach(c=>c.onchange=()=>{if(c.checked&&selected.size>=3){c.checked=false;alert('Compare up to three policy scopes at a time.');return}c.checked?selected.add(c.dataset.compare):selected.delete(c.dataset.compare);compare()})}
function compare(){const ps=policies.filter(p=>selected.has(p.id));$('compare').hidden=!ps.length;$('compare').innerHTML='<h3>Your comparison</h3><table><thead><tr><th>School & scope</th><th>Format</th><th>Ceiling</th></tr></thead><tbody>'+ps.map(p=>'<tr><td>'+p.school+'<br><small>'+p.scope+'</small></td><td>'+p.format+'</td><td>'+p.pct+'%</td></tr>').join('')+'</tbody></table><p class="note">No cost or speed ranking is assigned without program-specific pricing and scheduling. Compare full policies before choosing.</p>'}
['search','level','format','sort'].forEach(id=>$(id).addEventListener('input',render));
function inventory(){$('inventory').innerHTML=state.inventory.map((c,i)=>'<div class="inventory-row"><span><b>'+esc(c.name)+'</b> · '+esc(c.credits)+' credits<br>'+esc(c.source)+' · '+esc(c.status==='approved'?'School confirmed':c.status==='rejected'?'Not applicable':'Needs evaluation')+'</span><button data-remove="'+i+'" aria-label="Remove '+esc(c.name)+'">Remove</button></div>').join('');document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.inventory.splice(Number(b.dataset.remove),1);save();inventory();summary()})}
$('creditform').onsubmit=e=>{e.preventDefault();const credits=Number($('credits').value);if(!Number.isFinite(credits)||credits<=0)return;state.inventory.push({name:$('course').value.trim(),source:$('source').value,credits,status:$('status').value});$('course').value='';save();inventory();summary()};
function calculate(){const p=policies.find(p=>p.id===$('destination').value)||policies[0],required=Math.max(1,Number($('required').value)||1),approved=state.inventory.filter(c=>c.status==='approved').reduce((s,c)=>s+Number(c.credits),0),pending=state.inventory.filter(c=>c.status==='pending').reduce((s,c)=>s+Number(c.credits),0),cap=required*p.pct/100,planned=Math.max(0,Number($('planned').value)||0),applied=Math.min(approved,cap,required),remaining=required-applied,scenario=required-Math.min(approved+planned,cap,required),rate=Math.max(0,Number($('rate').value)||0),fees=Math.max(0,Number($('fees').value)||0),pace=Math.max(.1,Number($('pace').value)||.1);return{p,required,approved,pending,cap,planned,remaining,scenario,rate,fees,months:Math.ceil(scenario/pace),cost:scenario*rate+fees}}
function summary(){const s=calculate();$('summary').innerHTML='<span class="eyebrow" style="color:#dbf484">YOUR WORKING SCENARIO</span><div class="stats"><div><strong>'+s.approved+'</strong><small>self-reported approved credits</small></div><div><strong>'+s.pending+'</strong><small>credits awaiting evaluation</small></div><div><strong>'+Number(s.remaining.toFixed(1))+'</strong><small>credits left before planned transfer</small></div><div><strong>'+Number(s.scenario.toFixed(1))+'</strong><small>credits left if planned transfer is approved</small></div></div><p>'+(s.rate?'$'+s.cost.toLocaleString()+' scenario cost':'Enter a tuition quote to estimate cost')+' · '+s.months+' months at your entered pace</p><p class="note">Priority: '+esc($('priority').value)+'. This preference is saved for your plan; it does not rank schools yet. Timing excludes admission, prerequisites, term schedules and research milestones. Transfer calculations use only a general ceiling, not degree applicability.</p>'+(s.approved>s.cap?'<p>Check your inventory: approved credits exceed this policy ceiling.</p>':'')};
function renderTasks(){$('tasks').innerHTML=tasks.map((t,i)=>'<label class="task"><input type="checkbox" data-task="'+i+'" '+(state.tasks.includes(i)?'checked':'')+'>'+t+'</label>').join('');document.querySelectorAll('[data-task]').forEach(c=>c.onchange=()=>{const i=Number(c.dataset.task);state.tasks=state.tasks.filter(x=>x!==i);if(c.checked)state.tasks.push(i);save()})}
$('destination').addEventListener('change',()=>{state.inventory.forEach(c=>c.status='pending');state.tasks=[];save();inventory();renderTasks();summary();$('message').textContent='Destination changed. Credits and checklist need review for the new program.'});
function csvRows(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if(c==='\n'&&!quoted){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('Unclosed CSV quote');if(cell||row.length){row.push(cell.replace(/\r$/,''));rows.push(row)}return rows}
$('import').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>1000000){$('message').textContent='Please use a CSV smaller than 1 MB.';return}try{const rows=csvRows(await f.text());if(rows[0]?.[0]?.toLowerCase()==='name')rows.shift();const valid=rows.filter(r=>r[0]?.trim()&&Number.isFinite(Number(r[2]))&&Number(r[2])>0&&Number(r[2])<=200).map(r=>({name:r[0].slice(0,120),source:(r[1]||'College').slice(0,120),credits:Number(r[2]),status:'pending'}));state.inventory.push(...valid);save();inventory();summary();$('message').textContent=valid.length+' credits entries imported as unevaluated. '+(rows.length-valid.length)+' invalid rows skipped.'}catch{$('message').textContent='Could not parse CSV. Use columns name, source, credits, status.'}e.target.value=''};
$('export').onclick=()=>{const s=calculate(),text=['DegreeSteps — WORKING PLAN','Exported '+new Date().toISOString().slice(0,10),s.p.school+' — '+s.p.scope,'Goal: '+$('goal').value,'Policy source: '+s.p.url,'Policy research checked: 2026-10-28','Credit system: '+$('units').value,'Required: '+s.required+'; self-reported approved: '+s.approved+'; unevaluated: '+s.pending,'Planned additional transfer: '+s.planned,'Scenario remaining: '+s.scenario,'User-entered scenario cost: '+(s.rate?'$'+s.cost:'No tuition quote entered'),'Scenario months: '+s.months,'Priority: '+$('priority').value,'','INVENTORY',...state.inventory.map(c=>c.name+' | '+c.source+' | '+c.credits+' | '+c.status),'','CHECKLIST',...tasks.map((t,i)=>(state.tasks.includes(i)?'[x] ':'[ ] ')+t),'','NOTES',$('notes').value,'','Not an official degree audit. Get written school approval before purchasing courses. General transfer ceilings do not establish course equivalency or degree applicability.'].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='degreesteps-plan.txt';a.click();URL.revokeObjectURL(url)};
$('print').onclick=()=>window.print();$('clear').onclick=()=>{if(confirm('Clear this device’s saved plan? Download a copy first if needed.')){localStorage.removeItem('degreepath-v1');location.reload()}};
render();inventory();renderTasks();summary();
